34: static void RSLog(NSString *format, ...) {
35:     va_list args; va_start(args, format);
36:     NSString *line = [[NSString alloc] initWithFormat:format arguments:args]; va_end(args);
37:     NSString *out=[NSString stringWithFormat:@"[RS-FRESH-1.0.5] %@\n",line];
38:     NSLog(@"[RS-FRESH-1.0.5] %@",line);
39:     const char *path="/var/mobile/RecordingSharingan-Fresh.log";
40:     int fd=open(path,O_WRONLY|O_CREAT|O_APPEND,0644);
41:     if (fd>=0) { const char *bytes=out.UTF8String; if(bytes) write(fd,bytes,strlen(bytes));close(fd); }
42: }
