64: static BOOL RSIsPortal(UIView *v) {
65:     NSString *n=NSStringFromClass(v.class);
66:     return [n isEqualToString:@"SBSystemApertureSceneElementAccessoryPortalView"] ||
67:            [n isEqualToString:@"SBSystemApertureSceneElementAccessoryView"];
