69: static BOOL RSUsable(UIView *v) {
70:     return v && v.window && !v.hidden && v.alpha>0.01 &&
71:            CGRectGetWidth(v.bounds)>=8 && CGRectGetWidth(v.bounds)<=64 &&
72:            CGRectGetHeight(v.bounds)>=8 && CGRectGetHeight(v.bounds)<=64;
73: }
74: static void RSTrack(UIView *v) {
75:     if (!v || !RSIsPortal(v)) return;
76:     if (!RSCandidates) RSCandidates=[NSHashTable weakObjectsHashTable];
77:     if (RSUsable(v)) [RSCandidates addObject:v];
78:     else { [RSCandidates removeObject:v]; if (RSPreferred==v) RSPreferred=nil; }
79: }
